 "content": "from collections import deque

def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.pop()
                comp.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    z = (x+dx, y+dy)
                    if 0 <= z[0] < h and 0 <= z[1] < w and grid[z[0]][z[1]] == color and z not in seen:
                        seen.add(z)
                        q.append(z)
            out.append(comp)
    return out

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # The guide is the distinct, long L-shaped non-background component.
    guides = []
    for color in counts:
        if color == bg:
            continue
        for comp in _components(g, color):
            if len(comp) < 6:
                continue
            rs = [r for r,c in comp]; cs = [c for r,c in comp]
            r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
            box = (r1-r0+1)*(c1-c0+1)
            fill = len(comp)/box
            # Sparse elongated components are the L-shaped color key.
            if max(r1-r0+1,c1-c0+1) >= 5 and fill < 0.75:
                guides.append((len(comp), color, comp, (r0,r1,c0,c1)))
    if not guides:
        return g
    _, key, guide, (r0,r1,c0,c1) = max(guides, key=lambda x:x[0])
    # Locate the guide's elbow, then choose the largest separate object in the diagonally
    # opposite quadrant; the key color is copied onto that object.
    pts = set(guide)
    elbow = None
    for r,c in guide:
        neighbors = sum((r+dr,c+dc) in pts for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
        if neighbors >= 2:
            elbow = (r,c)
            break
    if elbow is None:
        elbow = (r0 if r0 == r1 else r1, c0 if c0 == c1 else c1)
    er,ec = elbow
    # infer the arms' outward directions from the guide's bounding box
    vertical = [r for r,c in guide if c == ec]
    horizontal = [c for r,c in guide if r == er]
    vdir = -1 if len(vertical) > 1 and min(vertical) < er else 1
    hdir = -1 if len(horizontal) > 1 and min(horizontal) < ec else 1
    # Opposite of the corner's occupied quadrant.
    target_r_sign = -vdir
    target_c_sign = -hdir
    candidates = []
    for color in counts:
        if color in (bg, key):
            continue
        for comp in _components(g, color):
            # Keep components wholly on the target side of the two guide arms.
            cr = sum(r for r,c in comp)/len(comp)
            cc = sum(c for r,c in comp)/len(comp)
            if (cr-er)*target_r_sign <= 0 or (cc-ec)*target_c_sign <= 0:
                continue
            candidates.append((len(comp), comp))
    if candidates:
        comp = max(candidates, key=lambda x:x[0])[1]
        for r,c in comp:
            g[r][c] = key
    return g

if __name__ == '__main__':
    pass
