    for r, c in pts:
        for vr, vc in ((1, 0), (-1, 0)):
            for hr, hc in ((0, 1), (0, -1)):
                v = {(rr, c) for rr in range(min(r, max(x for x, y in pts if y == c)), max(r, min(x for x, y in pts if y == c)) + 1)}
                # Generate the two straight rays outward from this elbow.
                v = {(rr, c) for rr in range(min(r, max((x for x,y in pts if y==c), default=r)), max(r, min((x for x,y in pts if y==c), default=r)) + 1)}
                h = {(r, cc) for cc in range(min(c, max((y for x,y in pts if x==r), default=c)), max(c, min((y for x,y in pts if x==r), default=c)) + 1)}
                if v | h != pts:
                    continue
                # Require the elbow to be a corner (one arm extends each way).
                vvals = [x for x,y in pts if y == c]
                hvals = [y for x,y in pts if x == r]
                if len(vvals) >= 3 and len(hvals) >= 3 and ((min(vvals) == r) != (max(vvals) == r)) and ((min(hvals) == c) != (max(hvals) == c)):
                    return (r, c, vvals, hvals)
    return None

